private string GetDepartmentName(int? departmentID)
{
    if (departmentID == null)
        return "";

    try
    {
        DataTable dtbDepartment = SYS_DepartmentService.Table;
        if (dtbDepartment == null)
            return "";

        DataRow[] drwDepartment = dtbDepartment.Select("DepartmentID = '" + departmentID.ToString() + "'");
        if (drwDepartment != null && drwDepartment.Length > 0 && !Convert.IsDBNull(drwDepartment[0]["DepartmentName"]))
            return Convert.ToString(drwDepartment[0]["DepartmentName"]);
    }
    catch
    {
    }

    return "";
}

